/** The seed a room seed deals at a level (Normal when none is asked): the level's own list. */
export function snakeLevelDealSeed(level: Level | null | undefined, roomSeed: number): number {
  const list = SNAKE_LEVEL_DEALS[level ?? "normal"] ?? SNAKE_LEVEL_DEALS.normal;
  const n = list.length;
  return list[((Math.trunc(roomSeed) % n) + n) % n]!;
}
